def resolve(path, cwd, links):
    def split_parts(p):
        return [c for c in p.split('/') if c != '' and c != '.']

    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path if cwd != '/' else '/' + path

    # initial components stack (reverse for efficient pop from end = front processing)
    components = split_parts(path)[::-1]
    current = '/'
    link_count = 0

    while components:
        comp = components.pop()
        if comp == '..':
            if current != '/':
                idx = current.rfind('/')
                if idx <= 0:
                    current = '/'
                else:
                    current = current[:idx]
        else:
            if current == '/':
                new_path = '/' + comp
            else:
                new_path = current + '/' + comp

            if new_path in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[new_path]
                if target.startswith('/'):
                    target_full = target
                else:
                    if current == '/':
                        target_full = '/' + target
                    else:
                        target_full = current + '/' + target
                target_parts = split_parts(target_full)
                # push these parts to be processed next, before any remaining ones
                for t in reversed(target_parts):
                    components.append(t)
            else:
                current = new_path

    return current

